createServer(async (req, res) => {
  const url = new URL(req.url, "http://localhost");
  if (url.pathname === "/healthz") {
    res.writeHead(200, { "content-type": "application/json" });
    return res.end(JSON.stringify({ ok: true, harness: "flow-list" }));
  }
  // The three real paths, exactly as src/server/routes.ts spells them.
  const KIND = { "/ma-liste": "list", "/ma-liste/vide": "list-empty", "/ma-liste/ajouter": "add-line" };
  const kind = KIND[url.pathname.replace(/\/+$/, "") || "/"];
  if (!kind) {
    res.writeHead(404, { "content-type": "text/plain; charset=utf-8" });
    return res.end("flow-list harness serves /ma-liste, /ma-liste/vide and /ma-liste/ajouter");
  }
  try {
    const started = Date.now();
    const data = await loadList(kind, url.search);
    const body = renderToString(h(Fragment, null, h(List, { data }), h(DList, { data })));
    const ms = Date.now() - started;
    res.writeHead(200, { "content-type": "text/html; charset=utf-8", "cache-control": "no-store", "server-timing": `render;dur=${ms}` });
    res.end(
      `<!doctype html><html lang="fr"><head><meta charset="utf-8">` +
      `<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">` +
      `<title>pyka — ma liste</title>${headLinks()}` +
      `<style>${tokenCss()}</style><style>${APP_CSS}</style><style>${LIST_CSS}</style>` +
      `</head><body><div id="root">${body}</div></body></html>`,
    );
  } catch (err) {
    const message = err && err.stack ? err.stack : String(err);
    console.error("[flow-list]", url.search, "\n", message);
    res.writeHead(500, { "content-type": "text/plain; charset=utf-8" });
    res.end(message);
  }
}).listen('127.0.0.1')#2

