createServer(async (req, res) => {
  const url = new URL(req.url, "http://localhost");
  if (url.pathname === "/healthz") {
    res.writeHead(200, { "content-type": "application/json" });
    return res.end(JSON.stringify({ ok: true, harness: "flow-search" }));
  }
  try {
    const out = await render(url.pathname, url.search.replace(/^\?/, ""));
    const html = `<!doctype html><html lang="fr"><head><meta charset="utf-8">` +
      `<meta name="viewport" content="width=device-width, initial-scale=1">` +
      `${out.head}<style>${APP_CSS}</style><style>${FLOW_CSS}</style></head>` +
      `<body><div id="root">${out.html}</div></body></html>`;
    res.writeHead(out.status, { "content-type": "text/html; charset=utf-8", "cache-control": "no-store" });
    res.end(html);
  } catch (err) {
    // The real message, never a generic 500: the field naming the cause is the one worth keeping.
    const message = err && err.stack ? err.stack : String(err);
    console.error("[harness]", url.pathname, "\n", message);
    res.writeHead(500, { "content-type": "text/html; charset=utf-8" });
    res.end(`<!doctype html><meta charset="utf-8"><body style="font:14px ui-monospace;padding:24px">` +
      `<h1>Le harnais n'a pas pu rendre ${url.pathname}</h1><pre>${message.slice(0, 2000)}</pre>`);
  }
}).listen('127.0.0.1')#2

