namesOf/Promise.all([
      catalogue(sql, [brand]),
      sql.query(
        `select si.store_item_id, si.category, si.raw_category, si.raw_is_frozen, si.image_url,
                coalesce(g.gtins, '{}') as gtins
         from store_item si
         left join (select store_item_id, array_agg(gtin) as gtins from store_item_gtin
                    where not is_instore_weighed group by store_item_id) g using (store_item_id)
         where si.brand = $1`, [brand]),
    ])
      .then(([cat, rows]) => {
        const extra = new Map(rows.map((r) => [String(r["store_item_id"]), r]));
        // A chain has a few hundred category paths over tens of thousands of rows: one string each.
        const interned = new Map<string, string>();
        const intern = (v: unknown): string | null => { const t = str(v); if (t === null) return null; const k = interned.get(t); if (k) return k; interned.set(t, t); return t; };
        const items = cat.items.filter((it) => it.chain === brand && extra.has(it.id));
        const ids = items.map((it) => it.id);
        const rowOf = (it: (typeof items)[number]): Row => extra.get(it.id) as Row;
        const gtins = items.map((it) => { const g = rowOf(it)["gtins"]; return Array.isArray(g) ? (g as unknown[]).map(String) : []; });
        const byGtin = new Map<string, string[]>();
        gtins.forEach((gs, i) => { for (const g of gs) byGtin.set(g, [...(byGtin.get(g) ?? []), ids[i] as string]); });
        const v: NameIndex = {
          at: Date.now(), ids,
          names: items.map((it) => { const f = fold(it.rawName); return f === it.name ? it.name : f; }),
          rawNames: items.map((it) => it.rawName), sizes: items.map((it) => it.rawSize),
          makers: items.map((it) => it.rawBrand),
          categories: items.map((it) => intern(rowOf(it)["category"])), paths: items.map((it) => intern(rowOf(it)["raw_category"])),
          frozen: items.map((it) => { const f = rowOf(it)["raw_is_frozen"]; return f === null || f === undefined ? null : f === true; }),
          images: items.map((it) => str(rowOf(it)["image_url"])), products: items.map((it) => it.productId), gtins,
          pos: new Map(ids.map((id, i) => [id, i])), byGtin,
        };
        slot.value = v;
        return v;
      })
      .finally()#0

