refreshTranslations/(async () => {
    let head: Record<string, unknown> | undefined;
    try {
      [head] = await sql.query("select count(*)::int as n, max(mined_at) as v from search_translation");
    } catch (err) {
      if ((err as { code?: string }).code !== "42P01") throw err;
    }
    const n = Number(head?.["n"] ?? 0);
    if (n === 0) {
      if (translations.source === "table") {
        TRANSLATE = fromModule();
        translations = { source: "module", rows: directed(TRANSLATE), version: null };
        console.log(`[pyka] word pairs: the table is ${head ? "empty" : "absent"}, back on the module`);
      }
      return;
    }
    const version = `${n}@${new Date(String(head?.["v"])).toISOString()}`;
    if (translations.version === version) return;
    const rows = await sql.query("select word_from, word_to from search_translation order by word_from, p desc, word_to");
    const m = new Map<string, string[]>();
    for (const r of rows) {
      const from = String(r["word_from"]), to = String(r["word_to"]);
      const l = m.get(from); if (l) l.push(to); else m.set(from, [to]);
    }
    TRANSLATE = m;
    translations = { source: "table", rows: rows.length, version };
    console.log(`[pyka] word pairs: ${rows.length} from the table (${version})`);
  })().catch()#0

